mapper.select:
SELECT o.id, o.order_no, o.product_id, o.buyer_id, o.seller_id, o.amount, o.status, o.remark, o.contact, o.finish_time, o.create_time, o.update_time, p.title AS productTitle, p.cover_image AS productCover, b.nickname AS buyerNickname, s.nickname AS sellerNickname FROM orders o LEFT JOIN product p ON o.product_id = p.id LEFT JOIN `user` b ON o.buyer_id = b.id LEFT JOIN `user` s ON o.seller_id = s.id
o.deleted = 0
AND o.seller_id = #{query.userId} AND o.buyer_id = #{query.userId}
AND o.status = #{query.status}
ORDER BY o.create_time DESC, o.id DESC
